    let same_hpos = unsafe { *same.offset(hpos as isize) }; // SAFETY: `hpos` is masked to the window range exactly as in the original code; `same` points to the hash window table.

    if TryGetFromLongestMatchCache(s, pos, &raw mut limit, sublen, distance, length) != 0 {
        return;
    }
    if size.wrapping_sub(pos) < ZOPFLI_MIN_MATCH as size_t {
        *length = 0 as c_ushort;
        *distance = 0 as c_ushort;
        return;
    }
    if pos.wrapping_add(limit) > size {
        limit = size.wrapping_sub(pos);
    }
    arrayend = unsafe { pos_ptr.offset(limit as isize) }; // SAFETY: `limit` was clamped so `pos + limit <= size`, matching the original pointer arithmetic.
    arrayend_safe = unsafe { arrayend.offset(-(8 as c_int as isize)) }; // SAFETY: preserves the original code's contract with `GetMatch`; no additional assumptions are introduced.
