        ZOPFLI_WINDOW_SIZE - p as c_int + pp as c_int
    }) as c_uint;
    while dist < ZOPFLI_WINDOW_SIZE as c_uint {
        let mut currentlength: c_ushort = 0 as c_ushort;
        if dist > 0 as c_uint {
            scan = pos_ptr;
            match_0 = unsafe { array.offset(pos.wrapping_sub(dist as size_t) as isize) as *const c_uchar }; // SAFETY: this uses the same distance-bounded backward reference as the original code.
