                let mut same0: c_ushort = same_hpos;
                if same0 as c_int > 2 as c_int
                    && unsafe { *scan as c_int == *match_0 as c_int }
                {
                    let mut same1: c_ushort = unsafe {
                        *same.offset(
                            (pos.wrapping_sub(dist as size_t) & ZOPFLI_WINDOW_MASK as size_t)
                                as isize,
                        )
                    }; // SAFETY: masked ring-buffer index, same as the original code.
                    let mut same_len: c_ushort =
                        (if (same0 as c_int) < same1 as c_int {
                            same0 as c_int
                        } else {
                            same1 as c_int
                        }) as c_ushort;
                    if same_len as size_t > limit {
                        same_len = limit as c_ushort;
                    }
                    scan = unsafe { scan.offset(same_len as c_int as isize) }; // SAFETY: offset is bounded by `limit`, matching the original code.
                    match_0 = unsafe { match_0.offset(same_len as c_int as isize) }; // SAFETY: offset mirrors `scan` exactly as in the original code.
                }
                scan = GetMatch(scan, match_0, arrayend, arrayend_safe);
                currentlength =
                    unsafe { scan.offset_from(pos_ptr) as c_long as c_ushort }; // SAFETY: both pointers derive from the same `array` allocation and this mirrors the original computation.
            }
