            && bestlength as c_int >= same_hpos as c_int
            && val2 == unsafe { *hashval2.offset(p as isize) }
        {
            hhead = head2;
            hprev = prev2;
            hhashval = hashval2;
            hval = val2;
        }
        pp = p;
        p = unsafe { *hprev.offset(p as isize) }; // SAFETY: `p` remains a hash-chain cursor exactly as in the original code.
        if p as c_int == pp as c_int {
            break;
        }
        dist = dist.wrapping_add(
            (if (p as c_int) < pp as c_int {
                pp as c_int - p as c_int
            } else {
                ZOPFLI_WINDOW_SIZE - p as c_int + pp as c_int
            }) as c_uint,
        );
        chain_counter -= 1;
        if chain_counter <= 0 as c_int {
            break;
        }
